// Tomcat.addServlet(...) zwraca obiekt Wrapper, reprezentujacy
// rejestracje serwletu w kontenerze - na NIM wywolujemy
// addInitParameter(name, value) PRZED tomcat.start().

Wrapper welcomeWrapper = Tomcat.addServlet(context, "welcomeServlet", new WelcomeServlet());
welcomeWrapper.addInitParameter("welcomeMessage", "Witaj w sklepie internetowym!");
welcomeWrapper.addInitParameter("maxItems", "50");
context.addServletMappingDecoded("/powitanie", "welcomeServlet");

// Ta sama klasa, INNA rejestracja - INNE parametry, niezalezne od pierwszej
Wrapper adminWrapper = Tomcat.addServlet(context, "adminServlet", new WelcomeServlet());
adminWrapper.addInitParameter("welcomeMessage", "Panel administratora");
context.addServletMappingDecoded("/admin", "adminServlet");

// Wewnatrz serwletu dostep do parametrow jest mozliwy na dwa
// (rownowazne) sposoby:

ServletConfig config = getServletConfig();
String welcomeMessage = config.getInitParameter("welcomeMessage"); // jawnie

// HttpServlet ma metode-wygode getInitParameter, ktora po prostu
// deleguje do getServletConfig().getInitParameter(...):
String welcomeMessageSkrot = getInitParameter("welcomeMessage"); // skrot

// Oba zwracaja DOKLADNIE ta sama wartosc.

Enumeration<String> names = config.getInitParameterNames();
List<String> nameList = Collections.list(names);
System.out.println(String.join(", ", nameList));

// Przydatne, gdy nie znamy nazw parametrow z gory w kodzie -
// pozwala zaiterowac po WSZYSTKICH parametrach danego serwletu.
